fn one_off(a: Str, b: Str) -> Bool {
  let ca = a.chars()
  let cb = b.chars()
  if ca.len() != cb.len() {
    return false
  }
  let diffs = range(0, ca.len()).count(fn(k) => ca.get_or(k, "") != cb.get_or(k, ""))
  return diffs == 1
}

pub fn ladder(start: Str, goal: Str, words: List[Str]) -> Int {
  if start == goal {
    return 1
  }
  let nodes = [start].concat(words)
  let n = nodes.len()
  var dist: List[Int] = range(0, n).map(fn(_k) => -1)
  dist = dist.set(0, 1)
  var queue: List[Int] = [0]
  var head = 0
  while head < queue.len() {
    let cur = queue.get_or(head, 0)
    head = head + 1
    let cur_word = nodes.get_or(cur, "")
    for j in range(0, n) {
      if dist.get_or(j, -1) == -1 and one_off(cur_word, nodes.get_or(j, "")) {
        dist = dist.set(j, dist.get_or(cur, 0) + 1)
        queue = queue.push(j)
      }
    }
  }
  let final_dist = dist
  let reached = range(0, n).filter(fn(j) => nodes.get_or(j, "") == goal and final_dist.get_or(j, -1) != -1)
  return reached.map(fn(j) => final_dist.get_or(j, 0)).min().unwrap_or(0)
}
